-- Migration: Year 2 - Sexual & Forensic Pathology MCQs Part 4 (116-155)
-- Date: 2026-04-24

BEGIN;

DO $$
DECLARE
    v_topic_id UUID;
BEGIN
    INSERT INTO topics (title, slug, semester_id, year_id, "order")
    VALUES ('Sexual & Forensic Pathology', 'sexual-forensic-pathology', 3, 2, 62)
    ON CONFLICT (slug) DO UPDATE SET year_id = 2, semester_id = 3
    RETURNING id INTO v_topic_id;

    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES

    -- VULVA & VAGINA (116-125)
    (v_topic_id, 'Lichen sclerosus of the vulva is characterized by?', '["Thick, leathery skin from chronic rubbing", "Thinning of the epidermis and fibrosis of the dermis, presenting as white plaques (parchment-like skin)", "Red, itchy, eczematous patch", "Multiple small ulcers"]', 1, 'Lichen sclerosus presents as thin, white "parchment-like" skin. It is most common in postmenopausal women. Histologically, there is thinning (atrophy) of the epidermis and sclerosis (fibrosis) of the dermis. It is associated with a slightly increased risk of squamous cell carcinoma.'),
    (v_topic_id, 'Lichen Simplex Chronicus is distinguished from Lichen Sclerosus by?', '["Atrophy of the epidermis", "Hyperplasia of the squamous epithelium (thickening) and no increased risk of cancer", "Presence of koilocytes", "Dermal fibrosis"]', 1, 'Lichen Simplex Chronicus is due to chronic scratching or rubbing. It results in squamous cell hyperplasia (leukoplakia) and leathery, thickened skin. Unlike Lichen Sclerosus, it does NOT carry an increased risk of malignancy.'),
    (v_topic_id, 'Extramammary Paget Disease of the vulva presents as a red, pruritic, ulcerated skin lesion. What distinguishes it from Paget disease of the breast?', '["It is always associated with underlying carcinoma", "It is usually NOT associated with an underlying invasive cancer (unlike breast Paget, which almost always indicates underlying DCIS or carcinoma)", "It only affects young women", "It is caused by HPV"]', 1, 'Vulvar Paget disease is an intraepithelial adenocarcinoma. While Paget of the nipple almost always signifies an underlying ductal carcinoma, Extramammary Paget (vulva, perianal) is usually confined to the epidermis without an underlying malignancy.'),
    (v_topic_id, 'Which tumor is associated with in utero exposure to Diethylstilbestrol (DES)?', '["Squamous cell carcinoma of the vagina", "Clear cell adenocarcinoma of the vagina", "Sarcoma botryoides", "Brenner tumor"]', 1, 'DES exposure in utero is a classic risk factor for the development of clear cell adenocarcinoma of the vagina and cervix in young women (daughters of mothers who took DES). It is also associated with uterine anomalies.'),
    (v_topic_id, 'Sarcoma botryoides (Embryonal Rhabdomyosarcoma) is a rare vaginal tumor. In whom does it typically occur?', '["Postmenopausal women", "Infants and children under age 5", "Teenagers", "Women in their 30s"]', 1, 'Sarcoma botryoides is a malignant mesenchymal tumor that presents as a "grape-like" mass protruding from the vagina of an infant or young girl. Histologically, it shows cross-striations (rhabdomyoblasts) and a "cambium layer" (dense zone of cells beneath the epithelium).'),

    -- CERVIX (126-135)
    (v_topic_id, 'The "transformation zone" of the cervix is?', '["The area between the inner and outer os", "The junction where the columnar epithelium of the endocervix meets the squamous epithelium of the ectocervix", "The site of mucus production", "The area least affected by HPV"]', 1, 'The transformation zone (squamocolumnar junction) is the most metabolically active area of the cervix and is the site where most cervical intraepithelial neoplasia (CIN) and squamous cell carcinomas arise.'),
    (v_topic_id, 'Cervical Intraepithelial Neoplasia (CIN) is graded based on the thickness of epithelial involvement. CIN III involves?', '["The lower 1/3 of the epithelium", "The entire thickness of the epithelium (carcinoma in situ)", "The lower 2/3 of the epithelium", "Invasion through the basement membrane"]', 1, 'CIN classification: CIN I = lower 1/3; CIN II = lower 2/3; CIN III = full thickness (but does NOT cross the basement membrane). Once it crosses the basement membrane, it is invasive carcinoma.'),
    (v_topic_id, 'HPV E6 and E7 oncoproteins drive cervical carcinogenesis by inhibiting which tumor suppressors?', '["E6 inhibits p53; E7 inhibits Rb", "E6 inhibits Rb; E7 inhibits p53", "Both inhibit p53", "Both inhibit Rb"]', 0, 'High-risk HPV (16, 18) DNA integrates into the host genome. E6 protein promotes the degradation of p53 (blocking apoptosis), and E7 protein binds and inactivates Rb (promoting cell cycle progression by releasing E2F).'),
    (v_topic_id, 'The Papanicolaou (Pap) smear is a screening tool for cervical cancer. What is the classic finding of HPV infection on a Pap smear?', '["Auer rods", "Koilocytes (cells with enlarged, dark nuclei and a perinuclear clear halo)", "Signet ring cells", "Psammoma bodies"]', 1, 'Koilocytic change is the cellular hallmark of HPV infection. Detecting these abnormal cells on a Pap smear allows for early intervention before progression to invasive cancer.'),
    (v_topic_id, 'What is the most common cause of death in patients with advanced, invasive cervical carcinoma?', '["Brain metastasis", "Uremia (renal failure) due to local invasion and obstruction of the ureters", "Liver failure", "Pulmonary embolism"]', 1, 'Cervical cancer tends to spread locally rather than to distant sites. It can invade the bladder or rectum and commonly obstructs the ureters, leading to hydronephrosis and eventually fatal renal failure (uremia).'),

    -- UTERUS: NON-NEOPLASTIC & LEIOMYOMA (136-155)
    (v_topic_id, 'Asherman Syndrome is characterized by secondary amenorrhea due to?', '["Pituitary adenoma", "Intrauterine adhesions (synechiae) usually following over-aggressive dilation and curettage (D&C)", "Ovarian failure", "Endometrial hyperplasia"]', 1, 'Asherman syndrome occurs when the "basalis" layer of the endometrium (the regenerative layer) is damaged, leading to scarring and loss of the uterine cavity. This results in amenorrhea and infertility.'),
    (v_topic_id, 'Chronic endometritis is diagnosed by the presence of which cell type on biopsy?', '["Neutrophils", "Plasma cells", "Lymphocytes", "Eosinophils"]', 1, 'While neutrophils are seen in acute endometritis (post-delivery/abortion), plasma cells are the essential diagnostic feature of chronic endometritis. Common causes include retained products of conception, PID, or IUDs.'),
    (v_topic_id, 'Endometriosis is defined as?', '["Overgrowth of the endometrium", "Endometrial glands and stroma located outside of the uterine cavity", "A malignant tumor of the uterus", "Hypertrophy of the myometrium"]', 1, 'Endometriosis most commonly involves the ovaries (forming "chocolate cysts"), but can also affect the pouch of Douglas, uterine ligaments, and peritoneum. It causes cyclic pelvic pain and dysmenorrhea.'),
    (v_topic_id, 'What is the "Retrograde Menstruation" theory of endometriosis?', '["Menstrual blood flows out of the vagina", "Menstrual tissue flows backwards through the fallopian tubes and implants onto pelvic organs", "Metaplasia of the coelomic epithelium", "Lymphatic spread of endometrial cells"]', 1, 'Retrograde menstruation (Sampson theory) is the most widely accepted theory. Other theories include the Metastatic theory (lymphatic/vascular spread) and the Metaplastic theory (coelomic metaplasia).'),
    (v_topic_id, 'Adenomyosis is defined as?', '["Endometrial tissue in the ovaries", "Endometrial glands and stroma within the myometrium (the muscular wall of the uterus)", "Infectious inflammation of the myometrium", "Metaplasia of the cervix"]', 1, 'Adenomyosis presents with an enlarged, "globular" uterus, heavy menstrual bleeding (menorrhagia), and dysmenorrhea. It is distinct from endometriosis, which occurs outside the uterus.'),
    (v_topic_id, 'Endometrial polyps are benign growths of the endometrium. What is a common clinical association?', '["DES exposure", "Tamoxifen therapy (due to its pro-estrogenic effect on the uterus)", "Vitamin C deficiency", "Multi-parity"]', 1, 'Tamoxifen is an ER antagonist in the breast but an ER agonist in the endometrium. This stimulation can lead to polyps, hyperplasia, and a slightly increased risk of endometrial carcinoma.'),
    (v_topic_id, 'Leiomyoma (fibroids) is the most common tumor in women. What is its origin?', '["Endometrial glands", "Benign smooth muscle cell of the myometrium", "Vascular endothelium", "Fibroblasts"]', 1, 'Leiomyomas are benign, monoclonal proliferations of smooth muscle. They are estrogen-sensitive (enlarge during pregnancy, shrink after menopause). Grossly, they are well-circumscribed, white, whorled masses.'),
    (v_topic_id, 'How do Leiomyomas typically present?', '["Always asymptomatic", "Often asymptomatic, but can cause menorrhagia (heavy bleeding), pelvic pressure, or infertility", "Weight loss and cachexia", "Vaginal discharge only"]', 1, 'While many are asymptomatic, their location matters. Submucosal fibroids often cause heavy bleeding. Large intramural or subserosal fibroids can cause bulk symptoms (pressure on bladder/rectum).'),
    (v_topic_id, 'Leiomyosarcoma is a malignant smooth muscle tumor. Does it typically arise from a pre-existing leiomyoma?', '["Yes, 50% of leiomyomas become sarcomas", "No, it almost always arises de novo (NOT from a leiomyoma)", "Only in postmenopausal women", "Only during pregnancy"]', 1, 'Leiomyosarcoma is a rare malignancy that arises directly from the myometrium, not from a benign "fibroid." Histological features include nuclear atypia, high mitotic rate, and "zonal necrosis."'),
    (v_topic_id, 'What is the characteristic clinical finding in a postmenopausal woman with leiomyosarcoma?', '["A shrinking uterus", "A rapidly enlarging uterus in a postmenopausal woman", "Sudden weight gain", "Amenorrhea"]', 1, 'Since benign leiomyomas shrink after menopause due to low estrogen, a rapidly growing uterine mass in a postmenopausal woman is highly suspicious for leiomyosarcoma.')

    ON CONFLICT DO NOTHING;

END $$;

COMMIT;
